body {
  min-height: 100vh;
  background:
    radial-gradient(1100px 600px at 85% -10%, rgba(90, 209, 255, 0.08), transparent 60%),
    radial-gradient(900px 500px at -10% 10%, rgba(139, 124, 255, 0.10), transparent 60%),
    var(--bg-0);
}

.page {
  max-width: 760px;
  margin: 0 auto;
  padding: 72px 24px 96px;
}

/* Hero */
.hero {
  text-align: center;
  margin-bottom: 48px;
}

.hero-badge {
  display: inline-block;
  font-size: 12px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--text-dim);
  background: var(--bg-2);
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 6px 14px;
  margin-bottom: 18px;
}

.hero h1 {
  font-size: clamp(36px, 6vw, 52px);
  margin: 0 0 14px;
  letter-spacing: -0.02em;
  background: linear-gradient(135deg, #ffffff 0%, #b8b3ff 60%, #5ad1ff 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}

.subtitle {
  color: var(--text-dim);
  font-size: 17px;
  line-height: 1.55;
  max-width: 520px;
  margin: 0 auto;
}

/* FAQ list */
.faq {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.example {
  background: linear-gradient(180deg, var(--bg-1), var(--bg-2));
  border: 1px solid var(--border);
  border-radius: 14px;
  overflow: hidden;
  transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
}

.example:hover {
  border-color: var(--border-strong);
}

.example.open {
  border-color: rgba(139, 124, 255, 0.45);
  box-shadow: 0 0 0 1px rgba(139, 124, 255, 0.12), 0 8px 30px -12px var(--glow);
}

/* Question button */
.question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 18px 20px;
  background: transparent;
  border: 0;
  color: var(--text);
  font: inherit;
  font-size: 16px;
  font-weight: 500;
  text-align: left;
  cursor: pointer;
  transition: background 0.15s ease;
}

.question:hover { background: rgba(255, 255, 255, 0.02); }

.question:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}

.q-text { line-height: 1.4; }

/* Chevron */
.chevron {
  flex: 0 0 auto;
  width: 22px;
  height: 22px;
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  transition: transform 0.25s ease, color 0.2s ease;
}

.chevron::before,
.chevron::after {
  content: "";
  position: absolute;
  width: 10px;
  height: 2px;
  background: currentColor;
  border-radius: 2px;
  transition: transform 0.25s ease;
}

.chevron::before { transform: translateX(-3px) rotate(45deg); }
.chevron::after  { transform: translateX(3px)  rotate(-45deg); }

.example.open .chevron {
  color: var(--accent);
  transform: rotate(180deg);
}

/* Details (controlled content) */
.details {
  overflow: hidden;
  max-height: 0;
  transition: max-height 0.3s ease;
  border-top: 1px solid transparent;
}

.example.open .details {
  border-top-color: var(--border);
}

.details[hidden] { display: block; }

.details p {
  margin: 0;
  padding: 16px 20px 20px;
  color: var(--text-dim);
  font-size: 15px;
  line-height: 1.65;
}

.details p strong { color: var(--text); font-weight: 600; }
.details p em { color: #c4befb; font-style: normal; }

/* Footer */
.foot {
  margin-top: 56px;
  text-align: center;
  color: var(--text-muted);
  font-size: 13px;
}

@media (max-width: 540px) {
  .page { padding: 48px 18px 64px; }
  .question { padding: 16px; font-size: 15px; }
  .details p { padding: 14px 16px 18px; }
}

@media (prefers-reduced-motion: reduce) {
  .details, .chevron, .chevron::before, .chevron::after, .example {
    transition: none;
  }
}
